-- 本域可恢复目录；控制操作和恢复决定不放在此库。
CREATE TABLE catalog_meta(singleton INTEGER PRIMARY KEY CHECK(singleton=1),data_epoch TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0 CHECK(revision>=0));
CREATE TABLE backup_runs(backup_id TEXT PRIMARY KEY,source_epoch TEXT NOT NULL,barrier_id TEXT NOT NULL DEFAULT '',status TEXT NOT NULL,manifest_hash TEXT NOT NULL DEFAULT '',manifest_json TEXT NOT NULL DEFAULT '',encrypted_manifest_ref TEXT NOT NULL DEFAULT '',key_id TEXT NOT NULL DEFAULT '',include_secrets INTEGER NOT NULL CHECK(include_secrets IN(0,1)),approved_by TEXT NOT NULL,approved_at TEXT NOT NULL,created_at TEXT NOT NULL,completed_at TEXT,issues_json TEXT NOT NULL DEFAULT '[]');
CREATE INDEX backup_runs_order ON backup_runs(created_at DESC,backup_id DESC);
CREATE TABLE backup_objects(backup_id TEXT NOT NULL REFERENCES backup_runs(backup_id),owner TEXT NOT NULL,snapshot_id TEXT NOT NULL,schema_version INTEGER NOT NULL,watermark INTEGER NOT NULL,object_hash TEXT NOT NULL,encrypted_ref TEXT NOT NULL,snapshot_json TEXT NOT NULL,PRIMARY KEY(backup_id,owner));
CREATE TABLE stored_objects(object_id TEXT PRIMARY KEY,owner TEXT NOT NULL,kind TEXT NOT NULL,sha256 TEXT NOT NULL,byte_size INTEGER NOT NULL CHECK(byte_size>=0),relative_path TEXT NOT NULL UNIQUE,schema_version INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE mirror_runs(mirror_id TEXT PRIMARY KEY,backup_id TEXT,manifest_hash TEXT NOT NULL DEFAULT '',local_commit TEXT NOT NULL DEFAULT '',remote_ref TEXT NOT NULL DEFAULT '',state TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE remote_config(config_id INTEGER PRIMARY KEY CHECK(config_id=1),url_without_credentials TEXT NOT NULL,branch TEXT NOT NULL,credential_ref TEXT NOT NULL,revision INTEGER NOT NULL,approved_by TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE protection_settings(setting_id INTEGER PRIMARY KEY CHECK(setting_id=1),settings_json TEXT NOT NULL,revision INTEGER NOT NULL,approved_by TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE operation_receipts(subject_id TEXT NOT NULL,function_id TEXT NOT NULL,operation_id TEXT NOT NULL,input_hash TEXT NOT NULL,result_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(subject_id,function_id,operation_id));
